      "कक्षा 6 से 10 के विद्यार्थियों और शिक्षकों के लिए NCERT आधारित डिजिटल शिक्षण और मूल्यांकन पोर्टल।",
      "6 முதல் 10ஆம் வகுப்பு மாணவர்களுக்கும் ஆசிரியர்களுக்கும் NCERT சார்ந்த டிஜிட்டல் கற்றல் மற்றும் மதிப்பீட்டுத் தளம்.",
      "6 ರಿಂದ 10ನೇ ತರಗತಿ ವಿದ್ಯಾರ್ಥಿಗಳು ಮತ್ತು ಶಿಕ್ಷಕರಿಗೆ NCERT ಆಧಾರಿತ ಡಿಜಿಟಲ್ ಕಲಿಕೆ ಮತ್ತು ಮೌಲ್ಯಮಾಪನ ಪೋರ್ಟಲ್.",
      "6 മുതൽ 10 ക്ലാസ് വിദ്യാർത്ഥികൾക്കും അധ്യാപകർക്കും NCERT അടിസ്ഥാനമാക്കിയ ഡിജിറ്റൽ പഠന, മൂല്യനിർണയ പോർട്ടൽ.",
