      "Pragyan (प्रज्ञान) గ్రామీణ, ప్రభుత్వ పాఠశాలల్లోని 6 నుండి 10 తరగతుల విద్యార్థులకు NCERT ఆధారిత వీడియో పాఠాలు, సహపాఠుల నోట్స్, గత పరీక్ష ప్రశ్నలు, ర్యాంకుల పట్టికలు, ఏఐ సహాయకుడిని అందిస్తుంది. తక్కువ ఇంటర్నెట్ వేగంతోనూ ఉపయోగించేందుకు డేటా సేవర్ ఉంది.",
      "Pragyan (प्रज्ञान) ग्रामीण और सरकारी विद्यालयों की कक्षा 6 से 10 के विद्यार्थियों के लिए NCERT आधारित वीडियो पाठ, साथियों के नोट्स, पिछले वर्षों के प्रश्न, रैंकिंग सूची और एआई शिक्षक लाता है। धीमे इंटरनेट के लिए डेटा सेवर भी उपलब्ध है।",
      "Pragyan (प्रज्ञान), கிராமப்புற மற்றும் அரசுப் பள்ளிகளில் 6 முதல் 10ஆம் வகுப்பு மாணவர்களுக்கு NCERT சார்ந்த காணொளிப் பாடங்கள், சக மாணவர்களின் குறிப்புகள், முந்தைய தேர்வு வினாக்கள், தரவரிசைப் பட்டியல் மற்றும் ஏஐ ஆசிரியரை வழங்குகிறது. குறைந்த இணைய வேகத்திற்கான தரவு சேமிப்பும் உள்ளது.",
      "Pragyan (प्रज्ञान) ಗ್ರಾಮೀಣ ಮತ್ತು ಸರ್ಕಾರಿ ಶಾಲೆಗಳ 6 ರಿಂದ 10ನೇ ತರಗತಿ ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ NCERT ಆಧಾರಿತ ವೀಡಿಯೊ ಪಾಠಗಳು, ಸಹಪಾಠಿಗಳ ಟಿಪ್ಪಣಿಗಳು, ಹಿಂದಿನ ಪರೀಕ್ಷೆ ಪ್ರಶ್ನೆಗಳು, ಶ್ರೇಯಾಂಕ ಪಟ್ಟಿ ಮತ್ತು ಎಐ ಶಿಕ್ಷಕರನ್ನು ಒದಗಿಸುತ್ತದೆ. ಕಡಿಮೆ ಇಂಟರ್ನೆಟ್ ವೇಗಕ್ಕಾಗಿ ಡೇಟಾ ಉಳಿತಾಯವೂ ಇದೆ.",
      "Pragyan (प्रज्ञान) ഗ്രാമീണ, സർക്കാർ സ്കൂളുകളിലെ 6 മുതൽ 10 ക്ലാസ് വിദ്യാർത്ഥികൾക്ക് NCERT അടിസ്ഥാനമാക്കിയ വീഡിയോ പാഠങ്ങൾ, സഹപാഠികളുടെ കുറിപ്പുകൾ, മുൻവർഷ ചോദ്യങ്ങൾ, റാങ്ക് പട്ടികകൾ, ഏഐ അധ്യാപകൻ എന്നിവ നൽകുന്നു. കുറഞ്ഞ ഇന്റർനെറ്റ് വേഗത്തിനായി ഡാറ്റ ലാഭിക്കൽ മോഡും ഉണ്ട്.",
