    "உங்கள் அத்தியாயத்தின் சுருக்கம், முக்கியக் குறிப்புகள் அல்லது எளிய விளக்கம்.",
    "ನಿಮ್ಮ ಅಧ್ಯಾಯದ ಸಾರಾಂಶ, ಮುಖ್ಯ ಅಂಶಗಳು ಅಥವಾ ಸರಳ ವಿವರಣೆ.",
    "നിങ്ങളുടെ അധ്യായത്തിന്റെ സംഗ്രഹം, പ്രധാന കാര്യങ്ങൾ, അല്ലെങ്കിൽ ലളിതമായ വിശദീകരണം.",
