    "ತರಗತಿ ಬದಲಾಯಿಸುವುದರಿಂದ ಅದರ ವಿಷಯ ಪಟ್ಟಿ ತೆರೆಯುತ್ತದೆ; ಪ್ರಗತಿ, XP, ಲೀಡರ್‌ಬೋರ್ಡ್‌ಗೆ ನಿಮ್ಮ ಸ್ವಂತ ತರಗತಿಯೇ ಪೂರ್ವನಿಯೋಜಿತ.",
