    "ஒவ்வொரு பாடத்திலும் NCERT கற்றல் விளைவு ஐடிகள் (LO-…) மற்றும் DIKSHA பாடநெறி குறியீடு உள்ளது — முழு வரைபடத்திற்கு எந்தப் பாடப் பக்கத்தையும் பாருங்கள். உதவிக்கு: 1800-11-8004.",
