    "ഓരോ പാഠത്തിലും NCERT ലേണിംഗ്-ഔട്ട്‌കം ഐഡികളും (LO-…) DIKSHA കോഴ്സ് കോഡും ഉണ്ട് — പൂർണ്ണ മാപ്പിംഗിന് ഏതെങ്കിലും പാഠ പേജ് കാണുക. സഹായത്തിന്: 1800-11-8004.",
