    "आपके लिखे उत्तर सहेज लिए गए। नीचे दी स्कोरिंग कुंजियों से उन्हें जाँचें (या पूरी योजना डाउनलोड कर शिक्षक के साथ कक्षा मूल्यांकन करें)।",
    "நீங்கள் எழுதிய விடைகள் சேமிக்கப்பட்டன. கீழே உள்ள ஒவ்வொரு மதிப்பெண் விசையுடனும் ஒப்பிடுங்கள் (அல்லது முழு திட்டத்தைப் பதிவிறக்கி ஆசிரியருடன் மதிப்பிடுங்கள்).",
    "ನೀವು ಬರೆದ ಉತ್ತರಗಳು ಉಳಿಸಲ್ಪಟ್ಟವು. ಕೆಳಗಿನ ಪ್ರತಿ ಅಂಕನ ಕೀಲಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ (ಅಥವಾ ಪೂರ್ಣ ಯೋಜನೆಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಶಿಕ್ಷಕರೊಂದಿಗೆ ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ).",
    "നിങ്ങൾ എഴുതിയ ഉത്തരങ്ങൾ സേവ് ചെയ്തു. താഴെയുള്ള ഓരോ സ്കോറിംഗ് കീയുമായി താരതമ്യം ചെയ്യുക (അല്ലെങ്കിൽ പൂർണ്ണ സ്കീം ഡൗൺലോഡ് ചെയ്ത് അധ്യാപകനുമായി വിലയിരുത്തുക).",
