    "നിങ്ങൾക്ക് ആറക്ക കോഡ് മെയിൽ ആകും; അത് പത്ത് മിനിറ്റിൽ കാലഹരണപ്പെടും, അഞ്ച് ശ്രമങ്ങൾ അനുവദനീയമാണ്.",
