  "Pragyan uses NCERT Learning Outcome mapping (e.g. LO-8-SCI-06) and DIKSHA QR codes. Local SQLite or permanent hosted SQLite stores your session data, depending on the deployment.": [
    "ప్రజ్ఞాన్ NCERT లెర్నింగ్ అవుట్‌కమ్ మ్యాపింగ్ (ఉదా. LO-8-SCI-06), DIKSHA QR కోడ్‌లను ఉపయోగిస్తుంది. డిప్లాయ్‌మెంట్‌ను బట్టి మీ సెషన్ డేటా లోకల్ SQLite లేదా పెర్మనెంట్ హోస్టెడ్ SQLiteలో నిల్వ ఉంటుంది.",
    "प्रज्ञान NCERT लर्निंग आउटकम मैपिंग (जैसे LO-8-SCI-06) और DIKSHA QR कोड का उपयोग करता है। परिनियोजन के अनुसार आपका सत्र डेटा स्थानीय SQLite या स्थायी होस्टेड SQLite में रहता है।",
    "பிரக்ஞான் NCERT கற்றல் விளைவு வரைபடம் (எ.கா. LO-8-SCI-06), DIKSHA QR குறியீடுகளைப் பயன்படுத்துகிறது. வரிசைப்படுத்தலைப் பொறுத்து உங்கள் அமர்வுத் தரவு உள்ளூர் SQLite அல்லது நிரந்தர ஹோஸ்டட் SQLite-இல் சேமிக்கப்படும்.",
    "ಪ್ರಜ್ಞಾನ NCERT ಕಲಿಕಾ ಫಲಿತಾಂಶ ನಕ್ಷೆ (ಉದಾ. LO-8-SCI-06), DIKSHA QR ಸಂಕೇತಗಳನ್ನು ಬಳಸುತ್ತದೆ. ನಿಯೋಜನೆಗೆ ತಕ್ಕಂತೆ ನಿಮ್ಮ ಅಧಿವೇಶನ ದತ್ತಾಂಶ ಸ್ಥಳೀಯ SQLite ಅಥವಾ ಶಾಶ್ವತ ಹೋಸ್ಟ್ ಮಾಡಿದ SQLiteನಲ್ಲಿ ಇರುತ್ತದೆ.",
    "പ്രജ്ഞാൻ NCERT ലേണിംഗ് ഔട്ട്‌കം മാപ്പിംഗ് (ഉദാ. LO-8-SCI-06), DIKSHA QR കോഡുകൾ ഉപയോഗിക്കുന്നു. ഡിപ്ലോയ്‌മെന്റിനനുസരിച്ച് നിങ്ങളുടെ സെഷൻ ഡാറ്റ ലോക്കൽ SQLite അല്ലെങ്കിൽ സ്ഥിര ഹോസ്റ്റഡ് SQLite-ൽ സൂക്ഷിക്കുന്നു.",
  ],

